import java.util.*;

public class Main {
    public static List<Integer> merge(List<Integer> left, List<Integer> right) {
        List<Integer> result = new ArrayList<>();
        int i = 0, j = 0;

        while (i < left.size() && j < right.size()) {
            if (left.get(i) <= right.get(j)) {
                result.add(left.get(i));
                i++;
            } else {
                result.add(right.get(j));
                j++;
            }
        }

        while (i < left.size()) {
            result.add(left.get(i));
            i++;
        }

        while (j < right.size()) {
            result.add(right.get(j));
            j++;
        }

        return result;
    }

    public static List<Integer> mergeSort(List<Integer> arr) {
        if (arr.size() <= 1) return arr;  // base case

        int mid = arr.size() / 2;

        List<Integer> left = new ArrayList<>(arr.subList(0, mid));
        List<Integer> right = new ArrayList<>(arr.subList(mid, arr.size()));

        left = mergeSort(left);
        right = mergeSort(right);

        return merge(left, right);
    }

    public static void main(String[] args) {
        List<Integer> arr = new ArrayList<>(List.of(8, 3, 5, 1, 7, 2, 6, 4));

        List<Integer> sorted = mergeSort(arr);

        for (int x : sorted) {
            System.out.print(x + " ");
        }
    }
}

